const token=process.env.NOTHING_HANDOFF_TOKEN;process.on('message',message=>{if(message.token!==token)return;if(message.type==='prepare')process.send({token,replyTo:'prepare',value:{ready:true,tabs:message.payload.tabs}});else if(message.type==='activate')process.send({token,replyTo:'activate',value:{active:true}});else if(message.type==='fail')process.send({token,replyTo:'fail',error:'fixture failure'});});
